002\u8bb0\u5f55\u5e76\u62a5\u544a\u88ab\u5254\u9664\u6761\u6570\uff08\u9884\u671f\u4e3b\u8981\u6765\u81ea MathInstruct \u5185\u5d4c\u7684 GSM8K/MATH \u8bad\u7ec3\u5b9e\u4f8b\uff09\u3002\n- \u5254\u9664\u540e\uff0c\u4efb\u610f\u8bc4\u6d4b\u6d4b\u8bd5\u6837\u672c**\u4e0d\u5f97**\u518d\u51fa\u73b0\u5728\u4efb\u4f55\u4e00\u7ec4\u7684\u8bad\u7ec3/dev \u6570\u636e\u4e2d\uff08\u4ee5\u89c4\u8303\u5316\u5339\u914d + \u4eba\u5de5\u62bd\u67e5\u53cc\u91cd\u9a8c\u8bc1\uff0c\u8f93\u51fa\u9a8c\u8bc1\u62a5\u544a\uff09\u3002\n- \u8bad\u7ec3\u4e0e\u8bc4\u6d4b\u5171\u7528\u540c\u4e00\u4efd\u6a21\u677f/\u5206\u8bcd/max_seq_len/\u89e3\u7801\u53c2\u6570/\u7b54\u6848\u62bd\u53d6\u811a\u672c\uff1bA\u3001B **\u4e0d\u5f97**\u5404\u81ea\u5b9a\u5236\u8bc4\u6d4b\u4ee3\u7801\u2014\u2014\u6700\u7ec8\u8bc4\u6d4b\u7edf\u4e00\u8c03\u7528\u540c\u4e00 `evaluate.py`\uff08\u7248\u672c\u9489\u4f4f\uff0c\u542b\u54c8\u5e0c\u6821\u9a8c\uff09\u3002\u4e24\u6cd5\u4ec5\u63d0\u4f9b\u5404\u81ea\u7684\u5df2\u5fae\u8c03\u6743\u91cd\uff0c\u8bc4\u6d4b\u5165\u53e3\u5b8c\u5168\u4e00\u81f4\u3002\n\n## 4. \u8bc4\u6d4b\u534f\u8bae\n\n- **\u57fa\u51c6**\uff1a\u4e3b\u57fa\u51c6 = GSM8K \u4e0e MATH\uff1b\u6269\u5c55\u516d\u57fa\u51c6\u9762 = GSM8K\u3001MATH\u3001MathQA\u3001SVAMP\u3001ASDiv\u3001TabMWP\uff08\u5bf9\u9f50 MAmmoTH\uff1b\u89c4\u6a21\u4e3a\u6e90\u6587\u732e\u8fd1\u4f3c\u503c\uff0c\u5982 GSM8K \u6d4b\u8bd5\u7ea6 1.3K\u3001MATH \u6d4b\u8bd5\u7ea6 5K\uff0c\u5c5e\u5916\u90e8\u5047\u8bbe\uff0c\u5de5\u4f5c\u533a\u5185\u4e0d\u53ef\u6838\u9a8c\uff09\uff1bAQuA \u53ef\u9009\u3002\n- **\u96f6\u6837\u672c**\uff1a\u65e0 in-context \u793a\u4f8b\uff1b\u7edf\u4e00\u5355\u6761\u63d0\u793a\u8bcd\u6a21\u677f\uff08\u4e0e\u8bad\u7ec3\u540c\u6a21\u677f\uff0c\u00a73\uff09\u3002\n- **\u751f\u6210\u8bbe\u7f6e**\uff1a\u8d2a\u5fc3\u89e3\u7801\uff08temperature=0\uff09\uff0c\u56fa\u5b9a max_new_tokens\uff08\u6765\u6e90\u9ed8\u8ba4\uff0c\u6807\u6ce8\u4e8e \u00a79\uff09\uff0c\u56fa\u5b9a repetition \u5904\u7406\u4e0e\u505c\u6b62\u6761\u4ef6\uff1b\u4e24\u6cd5\u9010\u5b57\u76f8\u540c\u3002\n- **\u7b54\u6848\u62bd\u53d6\u4e0e\u6253\u5206\uff08\u5171\u4eab\u811a\u672c\uff09**\uff1aGSM8K \u53d6 `####` \u540e\u7684\u6700\u7ec8\u7b54\u6848\uff1bMATH \u53d6 `\\boxed{}` \u5185\u7b54\u6848\uff1b\u6570\u503c\u5f52\u4e00\u5316\u540e\u4e0e\u53c2\u8003\u7b54\u6848 exact match\u3002\u6240\u6709\u57fa\u51c6\u8d70\u540c\u4e00\u89e3\u6790\u5668\uff1b\u4e24\u6cd5\u4e0d\u53ef\u5404\u81ea\u6539\u89e3\u6790\u89c4\u5219\u3002\n\n## 5. \u8bc4\u4ef7\u4e0e\u7edf\u8ba1\uff08\u9884\u6ce8\u518c\uff0c\u65e2\u5b9a\u53e3\u5f84\u7b2c 1 \u9879\uff09\n\n**\u6307\u6807**\uff1a\n- \u6bcf\u57fa\u51c6\u51c6\u786e\u7387\uff08final-answer exact match\uff09= \u6b21\u7ea7\u6307\u6807\u3002\n- **\u516d\u57fa\u51c6\u5b8f\u5e73\u5747\u51c6\u786e\u7387 = \u5355\u4e00\u4e3b\u6307\u6807**\uff08\u7528\u4e8e\u56de\u7b54\u201c\u662f\u5426\u66f4\u597d\u201d\u7684\u4e8c\u503c\u88c1\u5b9a\uff0c\u907f\u514d\u591a\u91cd\u6bd4\u8f83\u53e3\u5f84\u6df7\u4e71\uff09\u3002\n\n**\u79cd\u5b50\u4e0e\u5408\u5e76**\uff1a\u56fa\u5b9a\u79cd\u5b50\u7cfb\u5217 seed\u2208{0,1,2}\uff08N=3\uff1b\u9884\u7b97\u5141\u8bb8\u5219\u7528 5\uff0c\u4f46 N \u5728\u8fd0\u884c\u524d\u5b9a\u6b7b\u5e76\u8bb0\u5f55\uff09\u3002\u6bcf\u4e2a (\u7ec4 \u00d7 \u79cd\u5b50) \u8f93\u51fa\u5168\u5957\u8bc4\u6d4b\u7ed3\u679c\u3002\n\n**\u5224\u5b9a\u89c4\u5219\uff08\u8fd0\u884c\u524d\u56fa\u5b9a\uff0c\u7ed3\u679c\u4ea7\u751f\u540e\u4e0d\u6539\u52a8\uff09**\uff1a\n- H0\uff1a\u4e3b\u6307\u6807\u4e0a BAdam \u5747\u503c \u2212 LoRA \u5747\u503c = 0\uff1bH1\uff1a> 0\uff08\u5355\u4fa7\uff09\u3002\n- \u5408\u5e76\u65b9\u5f0f\uff1a\u6309\u79cd\u5b50\u914d\u5bf9\uff08seed i \u7684 A \u4e0e seed i \u7684 B \u914d\u5bf9\uff09\u3002\n- \u68c0\u9a8c\uff1a\u2460 \u914d\u5bf9 bootstrap\uff0810,000 \u6b21\u91cd\u91c7\u6837\uff09\u53cc\u4fa7 p \u4e0e 95% CI\uff1b\u2461 Welch t \u68c0\u9a8c\u3002\u4e24\u6cd5\u5747\u62a5\u544a\u3002\n- **\u88c1\u5b9a**\uff1aBAdam \u201c\u66f4\u597d\u201d \u27fa\uff08\u4e3b\u6307\u6807\u5747\u503c\u5dee > 0\uff09\u4e14\uff08bootstrap p < 0.05\uff0c\u03b1=0.05\uff09\u3002\u6548\u5e94\u91cf = \u767e\u5206\u70b9\u5dee\uff1b\u9644 95% CI\u3002\n- \u6bcf\u57fa\u51c6\uff08\u6b21\u7ea7\uff09\u540c\u6837\u62a5\u544a mean\u00b1std\u3001\u5747\u503c\u5dee\u3001bootstrap p\uff0c\u4f5c\u4e3a\u63cf\u8ff0\u6027\u8bc1\u636e\uff1b\u6700\u7ec8\u7ed3\u8bba\u4ee5\u4e3b\u6307\u6807\u88c1\u5b9a\u4e3a\u51c6\u3002\n- **\u9884\u6ce8\u518c\u58f0\u660e**\uff1a\u00a75 \u7684\u6307\u6807\u9009\u62e9\u3001\u68c0\u9a8c\u65b9\u6cd5\u3001\u03b1\u3001\u79cd\u5b50\u6570\u3001\u5408\u5e76\u4e0e\u88c1\u5b9a\u903b\u8f91\u5728\u8fd0\u884c\u524d\u5199\u5165\u5206\u6790\u8ba1\u5212\u5e76\u51bb\u7ed3\uff1b\u82e5\u8fd0\u884c\u540e\u51fa\u73b0\u4efb\u4f55\u8fdd\u80cc\u65e2\u5b9a\u53e3\u5f84\u7684\u64cd\u4f5c\uff0c\u987b\u5982\u5b9e\u8bb0\u5f55\u4e3a\u504f\u5dee\u5e76\u8bf4\u660e\u539f\u56e0\u3002\u672c\u8bbe\u8ba1\u6587\u6863\u5373\u4e3a\u8be5\u51bb\u7ed3\u8bb0\u5f55\u7684\u4e00\u90e8\u5206\uff0c\u5df2\u58f0\u660e\u201c\u672a\u5728\u7ed3\u679c\u4ea7\u751f\u540e\u6539\u52a8\u201d\u3002\n\n## 6. \u5b66\u4e60\u7387\u653f\u7b56\uff08\u65e2\u5b9a\u53e3\u5f84\u7b2c 2 \u9879\uff09\n\n- **\u9009\u62e9**\uff1aA \u4e0e B \u5728**\u7b49\u91cf\u8c03\u53c2\u9884\u7b97**\u5185\u5404\u81ea\u641c\u7d22\u6700\u4f18 LR\uff08\u5982\u5404\u81ea 5 \u4e2a\u5019\u9009 LR\uff0c\u5728\u5171\u4eab dev \u96c6\u4e0a\u6309\u4e3b\u6307\u6807\u9009\u51fa\uff09\uff0c\u5176\u4f59\u8d85\u53c2\u6570\u53d6\u6e90\u6587\u732e\u9ed8\u8ba4\u503c\uff08\u00a79\uff09\u3002\u80dc\u51fa LR \u5199\u5165\u914d\u7f6e\u5e76\u7528\u4e8e\u5168\u90e8\u79cd\u5b50\u8fd0\u884c\u3002\n- **\u4e3a\u4f55\u4f18\u4e8e\u5171\u7528\u540c\u4e00 LR**\uff1aBAdam \u662f**\u5168\u53c2\u6570**\u5757\u5f0f Adam \u66f4\u65b0\uff0c\u5178\u578b\u6700\u4f18 LR \u5904\u4e8e\u8f83\u5c0f\u91cf\u7ea7\uff08~1e-5 \u5c3a\u5ea6\uff09\uff1bLoRA \u53ea\u5728\u51bb\u7ed3\u6743\u91cd\u4e0a\u8bad\u7ec3\u5c11\u91cf\u4f4e\u79e9\u9002\u914d\u5668\uff0c\u5178\u578b\u6700\u4f18 LR \u5904\u4e8e\u8f83\u5927\u91cf\u7ea7\uff08~1e-4\u20131e-3 \u5c3a\u5ea6\uff09\u3002\u5f3a\u5236\u4e24\u6cd5\u5171\u7528\u540c\u4e00 LR \u4f1a\u7cfb\u7edf\u6027\u5730\u8ba9\u5176\u4e2d\u4e00\u65b9\u8fdc\u79bb\u5176\u6700\u4f18\u533a\u95f4\uff0c\u4ece\u800c\u626d\u66f2\u201c\u65b9\u6cd5\u6027\u80fd\u201d\u5bf9\u6bd4\uff1b\u7b49\u91cf\u9884\u7b97\u5404\u81ea\u641c\u7d22\u5728\u4fdd\u6301\u516c\u5e73\u7684\u524d\u63d0\u4e0b\u8ba9\u6bcf\u79cd\u65b9\u6cd5\u5728\u5176\u5408\u7406\u914d\u7f6e\u4e0b\u88ab\u8bc4\u4f30\u3002\n- **\u58f0\u660e**\uff1a\u6b64\u653f\u7b56\u4e0e\u4e24\u6cd5\u7684\u5178\u578b LR \u91cf\u7ea7\u5dee\u5f02\u5c5e**\u672c\u8bbe\u8ba1\u7684\u9009\u62e9/\u5047\u8bbe**\uff08\u57fa\u4e8e\u4f18\u5316\u7406\u8bba\u5e38\u89c1\u7ecf\u9a8c\uff09\uff0c**\u4e0d\u662f\u6e90\u6587\u732e\u4e8b\u5b9e**\uff1b\u6e90\u6587\u732e\u82e5\u62a5\u544a\u4e86\u5177\u4f53 LR\uff0c\u4f5c\u4e3a\u5019\u9009\u4e4b\u4e00\u7eb3\u5165\u641c\u7d22\u7a7a\u95f4\u5e76\u8bb0\u5f55\u3002\n- \u516c\u5e73\u6027\u62a4\u680f\uff1a\u8c03\u53c2\u9884\u7b97\uff08\u5019\u9009\u6570\u3001dev \u96c6\u3001\u641c\u7d22\u6307\u6807\u3001\u65e9\u505c\u56de\u5408\u6570\uff09\u5bf9\u4e24\u6cd5\u9010\u5b57\u76f8\u540c\uff0c\u5e76\u5728\u8fd0\u884c\u524d\u56fa\u5b9a\u3002\n\n## 7. \u63a7\u5236\u53d8\u91cf\u6e05\u5355\n\n- \u57fa\u5ea7\uff1a\u540c\u4e00 Meta-Llama-3-70B \u68c0\u67e5\u70b9\uff08\u9489\u4f4f revision/hash\uff09\u3002\n- \u6570\u636e\uff1a\u540c\u4e00\u53bb\u91cd\u526f\u672c\u3001\u540c\u6a21\u677f\u3001\u540c\u5206\u8bcd\u3001\u540c max_seq_len\u3001\u540c packing\u3001\u540c\u6d17\u724c\u79cd\u5b50\u3001\u540c\u904d\u5386\u987a\u5e8f\u3002\n- \u8bad\u7ec3\u9884\u7b97\uff1a\u540c\u4e00\u6b65\u6570/\u6570\u636e\u8f6e\u6b21\u3001\u540c\u4e00\u5168\u5c40\u6279\u5927\u5c0f\uff08\u6216\u6bcf\u6b65\u7b49\u4ef7 token \u6570\uff09\u3001\u540c warmup\u3001\u540c\u6743\u91cd\u8870\u51cf\u3001\u540c LR \u8c03\u5ea6\uff08cosine\uff09\u3001\u540c\u68af\u5ea6\u88c1\u526a\u8bbe\u7f6e\u3002\n- \u4f18\u5316\u5668\